#[derive(Clone, Copy, Debug)]
struct Observation {
    ok: bool,
    capacity: usize,
    work_left: usize,
    reserved: usize,
    overflowed: bool,
    metrics: Metrics,
}
#[allow(clippy::too_many_arguments)]
fn observe<'a>(
    programs: &'a [Program],
    authored: &'a BTreeMap<&'a str, AuthoredDeclaration<'a>>,
    old: bool,
    bytes: usize,
    work: usize,
    expected: Option<&Result<LayoutClosure<'a>, Vec<Diagnostic>>>,
) -> Observation {
    let ((result, metrics), overflowed, reserved, _) = with_limit_usage_refusal(bytes, || {
        measure(|| {
            let mut remaining = work;
            let answer = if old {
                LayoutClosure::derive_with_work_before_capacity(
                    &programs[0],
                    authored,
                    programs,
                    &mut remaining,
                    None,
                )
            } else {
                LayoutClosure::derive_with_work(
                    &programs[0],
                    authored,
                    programs,
                    &mut remaining,
                    None,
                )
            };
            if let Some(expected) = expected {
                match (&answer, expected) {
                    (Ok(a), Ok(b)) => same_layout(a, b),
                    (Err(a), Err(b)) => same_diagnostics(a, b),
                    _ => panic!("complete cold layout verdict differs"),
                }
            }
            let result = (
                answer.is_ok(),
                answer.as_ref().map_or(0, |r| r.entries.capacity()),
                remaining,
            );
            drop(answer);
            result
        })
    });
    assert!(!metrics.invalid);
    assert_eq!(metrics.live, 0);
    assert_eq!(metrics.allocated, metrics.freed);
    Observation {
        ok: result.0,
        capacity: result.1,
        work_left: result.2,
        reserved,
        overflowed,
        metrics,
    }
